(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-464":{scenario:{company:"Vạn Lộc Logistics",supervisor:{name:"Hoàng Gia Khánh",role:{vi:"Giám đốc Nhân sự",en:"HR Director"}},ref_code:"TAL-2604",title:{vi:"Xếp đúng ô nhân tài. Tính đúng nghỉ việc. Bảo vệ người lao động.",en:"Right talent box. Right turnover. Protect employees."},brief:{vi:"Đây là tình huống đào tạo. Bạn chuẩn bị báo cáo nhân sự năm TAL-2604 của khối kho vận trước họp ban giám đốc. Năm nay khối có 430 người đầu kỳ, 530 người cuối kỳ và 66 người nghỉ việc. Tại buổi hiệu chỉnh nhân tài, các trưởng bộ phận thống nhất trưởng kho Quang Vinh có hiệu suất cao nhưng tiềm năng ở mức trung bình. Đối chiếu báo cáo nháp với hồ sơ đã duyệt, sửa ô ma trận 9 ô và tỷ lệ nghỉ việc năm, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are preparing annual people report TAL-2604 for the warehousing division ahead of the board meeting. This year the division had 430 people at the start, 530 at the end and 66 leavers. At the talent calibration, department heads agreed that warehouse head Quang Vinh has high performance but medium potential. Compare the draft report with the approved file, correct the nine-box placement and the annual turnover rate, then write an evidence-based report."},reference_title:{vi:"Biên bản hiệu chỉnh & dữ liệu nhân sự đã chốt · TAL-2604",en:"Approved calibration minutes & locked HR data · TAL-2604"},fields:[{id:"NINE_BOX",label:{vi:"Ô ma trận 9 ô của trưởng kho Quang Vinh",en:"Nine-box placement of warehouse head Quang Vinh"},initial:"HP-HP",expected:"HP-MP",choices:["HP-HP","HP-MP","MP-HP"],reference:"Biên bản hiệu chỉnh nhân tài",hint:{vi:"Ký hiệu đầu là hiệu suất, ký hiệu sau là tiềm năng; hiệu suất cao không tự động đồng nghĩa tiềm năng cao.",en:"The first code is performance and the second is potential; high performance does not automatically mean high potential."}},{id:"TURNOVER",label:{vi:"Tỷ lệ nghỉ việc năm (%)",en:"Annual turnover rate (%)"},initial:"12.45",expected:"13.75",reference:"Dữ liệu nhân sự HRIS đã chốt",ref_value:{vi:"Đầu kỳ 430 người; cuối kỳ 530 người; số người nghỉ việc trong năm 66",en:"Opening headcount 430; closing headcount 530; leavers during the year 66"},hint:{vi:"Bản nháp chia cho quân số cuối kỳ; khi quân số tăng mạnh phải dùng quân số bình quân.",en:"The draft divided by closing headcount; when headcount grows fast, use the average headcount."}}],sop32:{vi:"Tỷ lệ nghỉ việc (%) = số người nghỉ việc trong kỳ / quân số bình quân x 100; quân số bình quân = (đầu kỳ + cuối kỳ) / 2; làm tròn 2 chữ số thập phân.",en:"Turnover rate (%) = leavers in the period / average headcount x 100; average headcount = (opening + closing) / 2; round to 2 decimal places."},context:{label:"HRIS / TAL-2604",metrics:[{label:{vi:"Quân số đầu kỳ",en:"Opening headcount"},value:"430"},{label:{vi:"Quân số cuối kỳ",en:"Closing headcount"},value:"530"},{label:{vi:"Số người nghỉ việc",en:"Leavers"},value:"66"}]},crisis:{vi:"Trưởng khối kho vận nhắn: “Chị Hạnh kế toán kho vừa báo có thai. Em đưa chị ấy vào danh sách ‘tái cấu trúc’ hoặc đừng gia hạn hợp đồng tháng sau giúp anh, mùa cao điểm không ai gánh được.”",en:"The head of warehousing messages you: “Ms Hanh, our warehouse accountant, just announced she is pregnant. Put her on the ‘restructuring’ list or don't renew her contract next month, nobody can cover her in peak season.”"},options:{safe:{vi:"Từ chối đưa chị Hạnh vào diện cắt giảm vì mang thai; tư vấn quy định bảo vệ lao động nữ, báo Giám đốc Nhân sự và pháp chế, đề xuất bố trí người hỗ trợ và kế hoạch bàn giao khi nghỉ thai sản.",en:"Refuse to target Ms Hanh because of pregnancy; explain the protections for female workers, inform the HR Director and Legal, and propose cover staff and a handover plan for her maternity leave."},shortcut:{vi:"Đưa chị Hạnh vào danh sách tái cấu trúc hoặc không gia hạn hợp đồng như quản lý yêu cầu.",en:"Put Ms Hanh on the restructuring list or let her contract lapse as the manager asked."},wait:{vi:"Không phản hồi, để trưởng khối tự xử lý với chị Hạnh.",en:"Do not respond and let the division head deal with Ms Hanh himself."}},questions:{vi:["Vì sao trưởng kho được xếp HP-MP và tỷ lệ nghỉ việc đúng là 13.75%? Kết quả này thay đổi khuyến nghị nhân sự thế nào?","Cắt giảm hoặc không gia hạn hợp đồng với lao động nữ vì mang thai vi phạm điều gì? Bạn tư vấn trưởng khối phương án hợp pháp nào?"],en:["Why is the warehouse head HP-MP, and why is turnover 13.75%? How do these results change your people recommendations?","What does cutting or not renewing a female worker because of pregnancy violate? Which lawful options do you advise the division head to use?"]},hints:{vi:["So báo cáo nháp với biên bản hiệu chỉnh: trục nào là hiệu suất, trục nào là tiềm năng?","Tính quân số bình quân trước, rồi chia số người nghỉ việc theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi quyết định nhân sự liên quan lao động nữ mang thai phải qua pháp chế và Giám đốc Nhân sự."],en:["Compare the draft with the calibration minutes: which axis is performance and which is potential?","Work out average headcount first, then divide leavers by it as in SOP 3.2.","Re-read SOP 4.2: any people decision involving a pregnant worker must go through Legal and the HR Director."]}},learning:{summary:{vi:"Chuyên viên đối tác nhân sự chiến lược (HRBP) đồng hành cùng lãnh đạo một khối kinh doanh, biến chiến lược thành kế hoạch con người: cơ cấu tổ chức, hoạch định nhân lực, quản trị nhân tài, hiệu suất, quan hệ lao động và văn hóa. Nghề tạo ra đội ngũ đủ năng lực và gắn kết, đòi hỏi hiểu kinh doanh, phân tích dữ liệu nhân sự, tư vấn thuyết phục và giữ vững chuẩn mực pháp lý, đạo đức.",en:"An HR business partner works alongside the leaders of a business unit to turn strategy into a people plan: organisation design, workforce planning, talent, performance, employee relations and culture. The role builds a capable and engaged team and requires business understanding, people analytics, persuasive advice and firm legal and ethical standards."},responsibilities:{vi:["Tham gia họp kinh doanh, chuyển mục tiêu khối thành kế hoạch nhân lực và ngân sách nhân sự.","Tư vấn quản lý về cơ cấu, tuyển dụng, điều chuyển, đánh giá và phát triển nhân viên.","Điều phối đánh giá hiệu suất, hiệu chỉnh nhân tài và kế hoạch kế thừa vị trí then chốt.","Phân tích chỉ số nghỉ việc, gắn kết, năng suất và đề xuất giải pháp giữ chân.","Xử lý vấn đề quan hệ lao động phức tạp cùng pháp chế, bảo đảm tuân thủ pháp luật."],en:["Join business reviews and turn unit goals into workforce plans and people budgets.","Advise managers on structure, hiring, transfers, appraisal and development.","Run performance reviews, talent calibration and succession plans for critical roles.","Analyse turnover, engagement and productivity and propose retention actions.","Handle complex employee relations cases with Legal and ensure legal compliance."]},competencies:[{name:{vi:"Hiểu biết kinh doanh",en:"Business acumen"},desc:{vi:"Đọc chỉ số kinh doanh của khối và liên hệ với năng lực, chi phí nhân sự.",en:"Read the unit's business metrics and link them to capability and people costs."}},{name:{vi:"Phân tích dữ liệu nhân sự",en:"People analytics"},desc:{vi:"Tính đúng tỷ lệ nghỉ việc, chi phí, năng suất và kể câu chuyện bằng dữ liệu.",en:"Compute turnover, cost and productivity correctly and tell the story with data."}},{name:{vi:"Tư vấn & ảnh hưởng",en:"Consulting & influence"},desc:{vi:"Đặt câu hỏi, phản biện quản lý và thuyết phục bằng lập luận, bằng chứng.",en:"Ask sharp questions, challenge managers and persuade with logic and evidence."}},{name:{vi:"Quản trị nhân tài",en:"Talent management"},desc:{vi:"Điều phối hiệu chỉnh, ma trận 9 ô, kế hoạch kế thừa và phát triển nhân tài.",en:"Lead calibration, the nine-box grid, succession and talent development."}},{name:{vi:"Tuân thủ & đạo đức",en:"Compliance & ethics"},desc:{vi:"Bảo vệ quyền người lao động, đặc biệt nhóm được pháp luật bảo vệ, và giữ bảo mật thông tin.",en:"Protect employee rights, especially legally protected groups, and keep information confidential."}}],knowledge:{vi:["Mô hình nhân sự ba trụ cột: HRBP, trung tâm chuyên môn (CoE) và trung tâm dịch vụ chung.","Ma trận 9 ô (hiệu suất x tiềm năng) và quy trình hiệu chỉnh nhân tài.","Bộ luật Lao động số 45/2019/QH14: cấm sa thải, đơn phương chấm dứt hợp đồng với lao động nữ vì kết hôn, mang thai, nghỉ thai sản, nuôi con dưới 12 tháng tuổi.","Khi thay đổi cơ cấu, công nghệ ảnh hưởng nhiều người, doanh nghiệp phải xây dựng phương án sử dụng lao động và trao đổi với tổ chức đại diện người lao động.","Chỉ số nhân sự cốt lõi: tỷ lệ nghỉ việc, nghỉ việc tự nguyện, chi phí nhân sự trên doanh thu, năng suất bình quân đầu người."],en:["The three-pillar HR model: HR business partners, centres of excellence and shared services.","The nine-box grid (performance x potential) and the talent calibration process.","Labour Code No. 45/2019/QH14: no dismissal or unilateral termination of female workers for marriage, pregnancy, maternity leave or raising a child under 12 months.","When structural or technological change affects many workers, the employer must prepare a labour use plan and consult the employee representative body.","Core people metrics: turnover, voluntary turnover, people cost to revenue and revenue per employee."]},tools:["Hệ thống thông tin nhân sự (HRIS)","Bảng điều khiển phân tích nhân sự","Công cụ khảo sát gắn kết","Phần mềm quản lý hiệu suất, mục tiêu","Bảng tính hoạch định nhân lực"],kpis:{vi:["Tỷ lệ nghỉ việc tự nguyện ngoài mong muốn của khối so với mục tiêu.","Tỷ lệ vị trí then chốt có người kế thừa sẵn sàng.","Điểm gắn kết của khối và mức cải thiện sau kế hoạch hành động.","Mức hài lòng của lãnh đạo khối với tư vấn nhân sự."],en:["Regretted voluntary turnover in the unit against target.","Share of critical roles with a ready successor.","Unit engagement score and its improvement after action plans.","Unit leaders' satisfaction with HR advice."]},day:[{time:"08:30",vi:"Đọc bảng điều khiển nhân sự tuần, đánh dấu biến động nghỉ việc bất thường.",en:"Review the weekly people dashboard and flag unusual turnover moves."},{time:"10:00",vi:"Dự giao ban kinh doanh khối kho vận, ghi nhận nhu cầu nhân lực mùa cao điểm.",en:"Attend the warehousing business review and note peak-season staffing needs."},{time:"13:30",vi:"Điều phối buổi hiệu chỉnh nhân tài với các trưởng bộ phận.",en:"Facilitate the talent calibration session with department heads."},{time:"15:30",vi:"Tư vấn quản lý một ca quan hệ lao động phức tạp cùng pháp chế.",en:"Advise a manager on a complex employee relations case with Legal."},{time:"17:00",vi:"Cập nhật kế hoạch giữ chân nhân tài và gửi tóm tắt cho Giám đốc Nhân sự.",en:"Update the retention plan and send a summary to the HR Director."}],mistakes:{vi:["Tính tỷ lệ nghỉ việc trên quân số cuối kỳ khi quân số biến động mạnh, làm sai bức tranh giữ chân.","Đồng nhất hiệu suất cao với tiềm năng cao, đề bạt sai người vào vị trí quản lý.","Chiều theo quản lý trong quyết định trái luật, như cắt giảm lao động nữ đang mang thai."],en:["Calculating turnover on closing headcount when headcount swings, distorting the retention picture.","Equating high performance with high potential and promoting the wrong person into management.","Going along with unlawful manager decisions, such as cutting a pregnant worker."]},career:[{vi:"Chuyên viên nhân sự tổng hợp",en:"HR generalist"},{vi:"Đối tác nhân sự (HRBP)",en:"HR business partner"},{vi:"HRBP cấp cao",en:"Senior HR business partner"},{vi:"Giám đốc nhân sự",en:"Chief people officer"}],glossary:[{term:"HRBP",vi:"Đối tác nhân sự chiến lược làm việc trực tiếp với lãnh đạo một khối kinh doanh.",en:"A strategic HR partner who works directly with the leaders of a business unit."},{term:"Nine-box grid",vi:"Ma trận 3 x 3 xếp nhân viên theo hiệu suất và tiềm năng để ra quyết định phát triển.",en:"A 3 x 3 grid placing employees by performance and potential to guide development decisions."},{term:"Calibration",vi:"Buổi hiệu chỉnh giúp các quản lý thống nhất tiêu chuẩn đánh giá giữa các đội.",en:"A session where managers align rating standards across teams."},{term:"Turnover rate",vi:"Tỷ lệ người nghỉ việc trên quân số bình quân trong kỳ.",en:"Leavers as a share of average headcount in the period."},{term:"Succession planning",vi:"Kế hoạch chuẩn bị người kế thừa sẵn sàng cho các vị trí then chốt.",en:"Preparing ready successors for critical positions."}],quiz:[{q:{vi:"Đầu kỳ 200 người, cuối kỳ 300 người, có 30 người nghỉ việc. Tỷ lệ nghỉ việc là bao nhiêu?",en:"Opening headcount is 200, closing is 300 and there were 30 leavers. What is the turnover rate?"},options:{vi:["10%","15%","12%","30%"],en:["10%","15%","12%","30%"]},answer:2,explain:{vi:"Quân số bình quân (200 + 300) / 2 = 250; 30 / 250 x 100 = 12%.",en:"Average headcount (200 + 300) / 2 = 250; 30 / 250 x 100 = 12%."}},{q:{vi:"Quản lý muốn chấm dứt hợp đồng với nhân viên đang nuôi con 8 tháng tuổi vì hay xin nghỉ. Bạn làm gì?",en:"A manager wants to terminate an employee raising an 8-month-old because she often takes leave. What do you do?"},options:{vi:["Làm theo nếu có bồi thường","Chuyển sang hợp đồng thời vụ","Gây áp lực để nhân viên tự nghỉ","Tư vấn đây là trái luật, báo Giám đốc Nhân sự và pháp chế"],en:["Comply if compensation is paid","Switch her to a seasonal contract","Pressure her to resign","Advise it is unlawful and inform the HR Director and Legal"]},answer:3,explain:{vi:"Pháp luật cấm chấm dứt hợp đồng với lao động nữ vì lý do nuôi con dưới 12 tháng tuổi.",en:"The law bans terminating female workers for raising a child under 12 months."}},{q:{vi:"Trong mô hình nhân sự ba trụ cột, bộ phận nào thiết kế chính sách chuyên sâu?",en:"In the three-pillar HR model, which unit designs specialist policy?"},options:{vi:["Trung tâm chuyên môn (CoE)","HRBP","Trung tâm dịch vụ chung","Công đoàn cơ sở"],en:["Centre of excellence (CoE)","HR business partner","Shared services centre","The workplace union"]},answer:0,explain:{vi:"CoE thiết kế chính sách chuyên môn như đãi ngộ, nhân tài; HRBP đưa chính sách vào khối kinh doanh.",en:"CoEs design expert policy such as reward and talent; HRBPs bring it into the business."}},{q:{vi:"Nhân viên có hiệu suất trung bình nhưng tiềm năng cao nên được ưu tiên thế nào?",en:"How should you prioritise an employee with medium performance but high potential?"},options:{vi:["Cho nghỉ việc","Huấn luyện, giao việc thử thách để nâng hiệu suất","Giữ nguyên, không can thiệp","Đề bạt ngay làm giám đốc"],en:["Let them go","Coach them and give stretch assignments to lift performance","Leave things as they are","Promote them to director at once"]},answer:1,explain:{vi:"Tiềm năng cao cần được khai thác bằng huấn luyện và việc thử thách trước khi giao vai trò lớn hơn.",en:"High potential is unlocked through coaching and stretch work before a bigger role."}}],tools_en:["Human resources information system (HRIS)","People analytics dashboard","Employee engagement survey tools","Performance and goal management software","Workforce planning spreadsheets"]}}})})(window.KKR);
